// Generated by python -m engine.generate; edit the authoritative WGSL files.
export const COMMON_SHADER = "// Generated by python -m engine.generate; edit engine/materials.json.
const SCHEMA_VERSION: u32 = 2u;
const MATERIAL_BITS: u32 = 8u;
const MATERIAL_SHIFT: u32 = 0u;
const MATERIAL_MASK: u32 = 255u;
const THERMAL_BITS: u32 = 8u;
const THERMAL_SHIFT: u32 = 8u;
const THERMAL_MASK: u32 = 255u;
const KINETIC_X_BITS: u32 = 4u;
const KINETIC_X_SHIFT: u32 = 16u;
const KINETIC_X_MASK: u32 = 15u;
const KINETIC_Y_BITS: u32 = 4u;
const KINETIC_Y_SHIFT: u32 = 20u;
const KINETIC_Y_MASK: u32 = 15u;
const PHASE_BITS: u32 = 4u;
const PHASE_SHIFT: u32 = 24u;
const PHASE_MASK: u32 = 15u;
const FLAGS_BITS: u32 = 4u;
const FLAGS_SHIFT: u32 = 28u;
const FLAGS_MASK: u32 = 15u;
const MAT_AIR: u32 = 0u;
const MAT_STONE: u32 = 1u;
const MAT_WATER: u32 = 2u;
const MAT_SAND: u32 = 3u;
const MAT_FIRE: u32 = 4u;
const MAT_METAL: u32 = 5u;
const MAT_OIL: u32 = 6u;
const MAT_WOOD: u32 = 7u;
const MAT_ICE: u32 = 8u;
const MAT_STEAM: u32 = 9u;
const MAT_LAVA: u32 = 10u;
const MAT_GLASS: u32 = 11u;
const MAT_PLAYER: u32 = 12u;
const MAT_ASH: u32 = 13u;
const MAT_SMOKE: u32 = 14u;
const MAT_OIL_VAPOR: u32 = 15u;
const MAT_MOLTEN_METAL: u32 = 16u;
const MAT_MOLTEN_GLASS: u32 = 17u;
const PHASE_SOLID: u32 = 0u;
const PHASE_POWDER: u32 = 1u;
const PHASE_LIQUID: u32 = 2u;
const PHASE_VISCOUS: u32 = 3u;
const PHASE_GAS: u32 = 4u;
const PHASE_PLASMA: u32 = 5u;
const PHASE_FROZEN: u32 = 6u;
const PHASE_MOLTEN: u32 = 7u;
const PHASE_BURNING: u32 = 8u;
const PHASE_CONDENSING: u32 = 9u;
const PHASE_EVAPORATING: u32 = 10u;
const PHASE_SUBLIMATING: u32 = 11u;
const FLAG_BURNING: u32 = 1u;
const FLAG_CONDUCTING: u32 = 2u;
const FLAG_PRESSURIZED: u32 = 4u;
const FLAG_PLAYER_OWNED: u32 = 8u;

struct VoxelState {
    material: u32,
    thermal: u32,
    kinetic_x: i32,
    kinetic_y: i32,
    phase: u32,
    flags: u32,
}

override GRID_WIDTH: u32 = 256u;
override GRID_HEIGHT: u32 = 256u;


// Seed 2: Branchless optimized pack/unpack
// Uses bitwise tricks to avoid branching for sign extension.

fn pack_voxel(mat: u32, thermal: u32, kx: i32, ky: i32, phase: u32, flags: u32) -> u32 {
    // Single expression pack — compiler can fuse these
    return ((mat & MATERIAL_MASK) << MATERIAL_SHIFT)
         | ((thermal & THERMAL_MASK) << THERMAL_SHIFT)
         | ((u32(kx) & KINETIC_X_MASK) << KINETIC_X_SHIFT)
         | ((u32(ky) & KINETIC_Y_MASK) << KINETIC_Y_SHIFT)
         | ((phase & PHASE_MASK) << PHASE_SHIFT)
         | ((flags & FLAGS_MASK) << FLAGS_SHIFT);
}

fn unpack_voxel(packed: u32) -> VoxelState {
    var state: VoxelState;
    state.material = (packed >> MATERIAL_SHIFT) & MATERIAL_MASK;
    state.thermal = (packed >> THERMAL_SHIFT) & THERMAL_MASK;

    // Branchless sign extension: (val ^ 0x8) - 0x8 converts 4-bit unsigned to signed
    let kx_raw = (packed >> KINETIC_X_SHIFT) & KINETIC_X_MASK;
    let ky_raw = (packed >> KINETIC_Y_SHIFT) & KINETIC_Y_MASK;
    state.kinetic_x = i32((kx_raw ^ 0x8u) - 0x8u);
    state.kinetic_y = i32((ky_raw ^ 0x8u) - 0x8u);

    state.phase = (packed >> PHASE_SHIFT) & PHASE_MASK;
    state.flags = (packed >> FLAGS_SHIFT) & FLAGS_MASK;
    return state;
}

fn exchange_thermal(a: u32, b: u32) -> vec2<u32> {
    // Branchless thermal exchange with configurable rate
    let ta = (a >> THERMAL_SHIFT) & THERMAL_MASK;
    let tb = (b >> THERMAL_SHIFT) & THERMAL_MASK;

    // Arithmetic shift for signed division
    let diff = i32(ta) - i32(tb);
    let transfer = diff >> 2;  // Divide by 4 via shift

    let new_ta = u32(max(min(i32(ta) - transfer, 255), 0));
    let new_tb = u32(max(min(i32(tb) + transfer, 255), 0));

    let clear_mask = ~(THERMAL_MASK << THERMAL_SHIFT);
    return vec2<u32>(
        (a & clear_mask) | (new_ta << THERMAL_SHIFT),
        (b & clear_mask) | (new_tb << THERMAL_SHIFT)
    );
}

// ── Compute entry point ────────────────────────────────────────────




// ca-v2 storage adapter. A cell is its packed view AND conserved energy.
@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;
@group(0) @binding(2) var<storage, read> cold_table: array<u32>;
@group(0) @binding(3) var<storage, read> energy_in: array<u32>;
@group(0) @binding(4) var<storage, read_write> energy_out: array<u32>;

const MAX_ENERGY_Q: u32 = 0x3fffffffu;
const NO_MATERIAL: u32 = 256u;
const NO_CELL: u32 = 0xffffffffu;

fn io_cold(material: u32, field: u32) -> u32 {
    return cold_table[material * 24u + field];
}

// Same logical property layout as Thermodynamics.gpu_table(); this adapter
// reads the authoritative cold table, so material edits need no shader rewrite.
fn property(material: u32, field: u32) -> u32 {
    switch field {
        case 0u: { return io_cold(material, 1u); }
        case 1u: { return io_cold(material, 19u) * 256u; }
        case 2u: { return io_cold(material, 16u) * 256u; }
        case 3u: {
            let boil = io_cold(material, 13u);
            if (boil != 0u) { return boil; }
            let melt = io_cold(material, 12u);
            return select(NO_MATERIAL, melt, melt != 0u);
        }
        case 4u: {
            if (io_cold(material, 13u) != 0u) { return io_cold(material, 3u) * 256u; }
            return io_cold(material, 2u) * 256u;
        }
        case 5u: {
            let freeze = io_cold(material, 14u);
            if (freeze != 0u) { return freeze; }
            let condense = io_cold(material, 15u);
            return select(NO_MATERIAL, condense, condense != 0u);
        }
        case 6u: {
            if (io_cold(material, 14u) != 0u) { return io_cold(material, 8u) * 256u; }
            return io_cold(material, 9u) * 256u;
        }
        case 7u: { return io_cold(material, 17u); }
        case 8u: { return io_cold(material, 18u); }
        case 9u: { return io_cold(material, 21u); }
        case 10u: { return io_cold(material, 4u) * 256u; }
        default: { return 0u; }
    }
}

fn io_state(index: u32) -> vec2<u32> {
    return vec2<u32>(grid_in[index] & MATERIAL_MASK, energy_in[index]);
}

fn io_copy(destination: u32, source: u32) {
    grid_out[destination] = grid_in[source];
    energy_out[destination] = energy_in[source];
}

fn io_write(index: u32, packed: u32, energy: u32) {
    let temperature = min(255u, temperature_q(vec2<u32>(packed & MATERIAL_MASK, energy)) / 256u);
    grid_out[index] = (packed & 0xffff00ffu) | (temperature << THERMAL_SHIFT);
    energy_out[index] = energy;
}

fn io_rewrite(packed: u32, material: u32) -> u32 {
    return (packed & 0xf0ff0000u) | material | (io_cold(material, 20u) << PHASE_SHIFT);
}

// Shared integer energy law; property() is supplied by the storage adapter.
fn temperature_q(state: vec2<u32>) -> u32 {
    let heat = state.y - property(state.x, 2u);
    let phase_energy = property(state.x, 1u);
    var temperature = u32(max(0, i32(heat) - i32(phase_energy)));
    let up = property(state.x, 3u);
    let up_temperature = property(state.x, 4u);
    let down = property(state.x, 5u);
    let down_temperature = property(state.x, 6u);
    if (up != NO_MATERIAL && heat >= phase_energy + up_temperature) {
        temperature = u32(max(i32(up_temperature), i32(heat) - i32(property(up, 1u))));
    } else if (down != NO_MATERIAL && heat <= phase_energy + down_temperature) {
        temperature = min(down_temperature, u32(max(0, i32(heat) - i32(property(down, 1u)))));
    }
    return temperature;
}

fn phase_material(state: vec2<u32>) -> u32 {
    let chemical = property(state.x, 2u);
    let up = property(state.x, 3u);
    if (up != NO_MATERIAL) {
        let boundary = chemical + property(up, 1u) + property(state.x, 4u);
        if (state.y >= boundary) { return up; }
    }
    let down = property(state.x, 5u);
    if (down != NO_MATERIAL) {
        let boundary = chemical + property(down, 1u) + property(state.x, 6u);
        if (state.y <= boundary) { return down; }
    }
    return state.x;
}

fn pair_energy(a: vec2<u32>, b: vec2<u32>) -> u32 {
    let temp_a = temperature_q(a);
    let temp_b = temperature_q(b);
    let ca = property(a.x, 0u);
    let cb = property(b.x, 0u);
    var conductivity = 0u;
    if (ca + cb > 0u) { conductivity = 2u * ca * cb / (ca + cb); }
    let difference = u32(abs(i32(temp_a) - i32(temp_b)));
    // Avoid overflowing difference * conductivity in u32 arithmetic.
    var flux = difference / 512u * conductivity + (difference % 512u * conductivity + 511u) / 512u;
    flux = min(flux, difference / 2u);
    if (temp_a > temp_b) {
        flux = min(flux, min(a.y - property(a.x, 2u), MAX_ENERGY_Q - b.y));
        return a.y - flux;
    }
    flux = min(flux, min(b.y - property(b.x, 2u), MAX_ENERGY_Q - a.y));
    return a.y + flux;
}


