// Conservative horizontal liquid spread.
//
// Each pass partitions rows into disjoint horizontal pairs. Direction is chosen
// by a deterministic coordinate hash plus MOVE_SALT to avoid global drift.


const COLD_STRIDE: u32 = 24u;
const COLD_DENSITY: u32 = 0u;
override MOVE_PHASE: u32 = 0u;
override MOVE_SALT: u32 = 0u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }

fn density_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];
}

fn is_structural(ph: u32) -> bool {
    return ph == PHASE_SOLID || ph == PHASE_FROZEN;
}

fn is_liquid_like(ph: u32) -> bool {
    return ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;
}

fn is_falling_matter(ph: u32) -> bool {
    return ph == PHASE_POWDER || ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_MOLTEN;
}

fn can_fall_into(src: u32, dst: u32) -> bool {
    let src_phase = get_phase(src);
    let dst_phase = get_phase(dst);
    if (!is_falling_matter(src_phase) || is_structural(dst_phase)) {
        return false;
    }
    return density_of(get_material(src)) > density_of(get_material(dst));
}

fn has_down_or_diagonal_fall(x: u32, y: u32, src: u32) -> bool {
    if (y >= GRID_HEIGHT - 1u) { return false; }
    if (can_fall_into(src, grid_in[get_idx(x, y + 1u)])) { return true; }
    if (x > 0u && can_fall_into(src, grid_in[get_idx(x - 1u, y + 1u)])) { return true; }
    if (x < GRID_WIDTH - 1u && can_fall_into(src, grid_in[get_idx(x + 1u, y + 1u)])) { return true; }
    return false;
}

fn can_spread_into(src: u32, dst: u32) -> bool {
    if (!is_liquid_like(get_phase(src)) || is_structural(get_phase(dst))) {
        return false;
    }
    let dst_phase = get_phase(dst);
    if (dst_phase != PHASE_GAS && get_material(dst) != MAT_AIR) {
        return false;
    }
    return density_of(get_material(src)) > density_of(get_material(dst));
}

fn hash_pair(x: u32, y: u32, salt: u32) -> u32 {
    var h = x * 374761393u + y * 668265263u + salt * 1442695041u;
    h = (h ^ (h >> 13u)) * 1274126177u;
    return h ^ (h >> 16u);
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    var pair_left = x;
    if (((x + MOVE_PHASE) & 1u) != 0u) {
        if (x == 0u) {
            io_copy(idx, idx);
            return;
        }
        pair_left = x - 1u;
    }
    if (pair_left >= GRID_WIDTH - 1u) {
        io_copy(idx, idx);
        return;
    }

    let left = grid_in[get_idx(pair_left, y)];
    let right = grid_in[get_idx(pair_left + 1u, y)];
    let left_can = !has_down_or_diagonal_fall(pair_left, y, left) && can_spread_into(left, right);
    let right_can = !has_down_or_diagonal_fall(pair_left + 1u, y, right) && can_spread_into(right, left);
    let source_left = select(
        left_can,
        (hash_pair(pair_left, y, MOVE_SALT) & 1u) == 0u,
        left_can && right_can,
    );
    let src_x = select(pair_left + 1u, pair_left, source_left);
    let dst_x = select(pair_left, pair_left + 1u, source_left);
    let src = select(right, left, source_left);
    let dst = select(left, right, source_left);
    let do_swap = left_can || right_can;

    if (do_swap && x == src_x) {
        io_copy(idx, get_idx(dst_x, y));
        return;
    }
    if (do_swap && x == dst_x) {
        io_copy(idx, get_idx(src_x, y));
        return;
    }

    io_copy(idx, idx);
}

sources.engine/kernels/phase_2b_winner.wgsl:
// Conservative vertical matter gravity with phased symmetric density swaps.
//
// Movement is limited to disjoint row pairs selected by GRAVITY_PHASE, so a
// cell can participate in at most one swap per pass and per-material counts are
// preserved exactly. Gas is handled by separate buoyancy/spread passes.


const COLD_STRIDE: u32 = 24u;
const COLD_DENSITY: u32 = 0u;
override GRAVITY_PHASE: u32 = 0u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }

fn density_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];
}

fn is_structural(ph: u32) -> bool {
    return ph == PHASE_SOLID || ph == PHASE_FROZEN;
}

fn is_vertical_falling_matter(ph: u32) -> bool {
    return ph == PHASE_SOLID
        || ph == PHASE_FROZEN
        || ph == PHASE_POWDER
        || ph == PHASE_LIQUID
        || ph == PHASE_VISCOUS
        || ph == PHASE_MOLTEN;
}

fn should_swap(upper: u32, lower: u32) -> bool {
    let upper_mat = get_material(upper);
    let lower_mat = get_material(lower);
    let upper_phase = get_phase(upper);
    let lower_phase = get_phase(lower);

    if (!is_vertical_falling_matter(upper_phase) || is_structural(lower_phase)) {
        return false;
    }

    return density_of(upper_mat) > density_of(lower_mat);
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    if (y < GRID_HEIGHT - 1u && ((y & 1u) == GRAVITY_PHASE)) {
        let below = grid_in[get_idx(x, y + 1u)];
        if (should_swap(voxel, below)) {
            io_copy(idx, get_idx(x, y + 1u));
            return;
        }
    }

    if (y > 0u && (((y - 1u) & 1u) == GRAVITY_PHASE)) {
        let above = grid_in[get_idx(x, y - 1u)];
        if (should_swap(above, voxel)) {
            io_copy(idx, get_idx(x, y - 1u));
            return;
        }
    }

    io_copy(idx, idx);
}

sources.engine/kernels/phase_2c_winner.wgsl:
// ca-v2: phase changes preserve the complete energy coordinate.
@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    if (gid.x >= GRID_WIDTH || gid.y >= GRID_HEIGHT) { return; }
    let index = gid.y * GRID_WIDTH + gid.x;
    let material = phase_material(io_state(index));
    var packed = grid_in[index];
    if (material != (packed & MATERIAL_MASK)) { packed = io_rewrite(packed, material); }
    io_write(index, packed, energy_in[index]);
}

sources.engine/kernels/phase_2d_winner.wgsl:
// ca-v2: conserved, mutually owned fuel/oxidizer reactions.
fn neighbor(index: u32, order: u32) -> u32 {
    let x = index % GRID_WIDTH;
    let y = index / GRID_WIDTH;
    var directions = array<u32, 4>(2u, 1u, 3u, 0u);
    if ((x + y) % 2u != 0u) { directions = array<u32, 4>(0u, 2u, 1u, 3u); }
    let direction = directions[order];
    if (direction == 0u && x > 0u) { return index - 1u; }
    if (direction == 1u && x + 1u < GRID_WIDTH) { return index + 1u; }
    if (direction == 2u && y > 0u) { return index - GRID_WIDTH; }
    if (direction == 3u && y + 1u < GRID_HEIGHT) { return index + GRID_WIDTH; }
    return NO_CELL;
}

fn burning(state: vec2<u32>) -> bool {
    return property(state.x, 2u) > 0u && temperature_q(state) > property(state.x, 10u);
}

fn chosen_air(index: u32) -> u32 {
    if (!burning(io_state(index))) { return NO_CELL; }
    for (var order = 0u; order < 4u; order += 1u) {
        let candidate = neighbor(index, order);
        if (candidate != NO_CELL) {
            if (property(io_state(candidate).x, 9u) == 1u) { return candidate; }
        }
    }
    return NO_CELL;
}

fn chosen_fuel(index: u32) -> u32 {
    for (var order = 0u; order < 4u; order += 1u) {
        let candidate = neighbor(index, order);
        if (candidate != NO_CELL) {
            if (chosen_air(candidate) == index) { return candidate; }
        }
    }
    return NO_CELL;
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    if (gid.x >= GRID_WIDTH || gid.y >= GRID_HEIGHT) { return; }
    let index = gid.y * GRID_WIDTH + gid.x;
    let state = io_state(index);
    var packed = grid_in[index];
    var energy = state.y;
    if (burning(state)) {
        let air = chosen_air(index);
        if (air != NO_CELL) {
            if (chosen_fuel(air) == index) {
                let transfer = min(property(state.x, 2u) / 2u, MAX_ENERGY_Q - energy_in[air]);
                packed = io_rewrite(packed, property(state.x, 7u));
                energy = state.y - transfer;
            }
        }
    } else if (property(state.x, 9u) == 1u) {
        let fuel = chosen_fuel(index);
        if (fuel != NO_CELL) {
            let transfer = min(property(io_state(fuel).x, 2u) / 2u, MAX_ENERGY_Q - state.y);
            packed = io_rewrite(packed, property(io_state(fuel).x, 8u));
            energy = state.y + transfer;
        }
    } else if (state.x == MAT_FIRE) {
        // Fire marks a local reaction. Its finite heat survives as smoke when
        // fuel is absent, it cools, or liquid water interrupts the flame.
        var fuel_near = false;
        var water_near = false;
        for (var order = 0u; order < 4u; order += 1u) {
            let candidate = neighbor(index, order);
            if (candidate != NO_CELL) {
                fuel_near = fuel_near || property(io_state(candidate).x, 2u) > 0u;
                water_near = water_near || io_state(candidate).x == MAT_WATER;
            }
        }
        if (!fuel_near || water_near || temperature_q(state) < 80u * 256u) {
            packed = io_rewrite(packed, MAT_SMOKE);
        }
    }
    io_write(index, packed, energy);
}

