"""A host-owned harness calls codec helpers and observes their individual fields."""

from contextlib import ExitStack

import numpy as np
import wgpu

from engine.resources import shader_source
from eval.benchmark import distribution, synchronized_sample
from eval.policy import candidate_lint, digest


HARNESS = """
@group(0) @binding(0) var<storage,read> probe_input: array<vec2<u32>>;
@group(0) @binding(1) var<storage,read_write> probe_output: array<u32>;
@compute @workgroup_size(64)
fn probe(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= arrayLength(&probe_input)) { return; }
    let a = probe_input[i].x;
    let b = probe_input[i].y;
    let v = unpack_voxel(a);
    let out = i * 9u;
    // Inputs to pack are independently decoded, not taken from the candidate's unpack.
    probe_output[out] = pack_voxel(a & 255u, (a >> 8u) & 255u,
        i32((a >> 16u) & 15u) - select(0, 16, ((a >> 16u) & 15u) >= 8u),
        i32((a >> 20u) & 15u) - select(0, 16, ((a >> 20u) & 15u) >= 8u),
        (a >> 24u) & 15u, (a >> 28u) & 15u);
    probe_output[out+1u] = v.material;
    probe_output[out+2u] = v.thermal;
    probe_output[out+3u] = bitcast<u32>(v.kinetic_x);
    probe_output[out+4u] = bitcast<u32>(v.kinetic_y);
    probe_output[out+5u] = v.phase;
    probe_output[out+6u] = v.flags;
    let exchange = exchange_thermal(a, b);
    probe_output[out+7u] = exchange.x;
    probe_output[out+8u] = exchange.y;
}
"""


def codec_vectors(seed: int, count: int = 16384) -> np.ndarray:
    rng = np.random.default_rng(seed)
    basis = np.array([0, 0xffffffff, *(1 << bit for bit in range(32)), *(0xffffffff ^ (1 << bit) for bit in range(32))], dtype=np.uint32)
    random = rng.integers(0, 2**32, size=(count, 2), dtype=np.uint32)
    return np.concatenate((np.column_stack((basis, basis[::-1])), random))


def codec_expected(vectors: np.ndarray) -> np.ndarray:
    a, b = vectors[:, 0].astype(np.int64), vectors[:, 1].astype(np.int64)
    ta, tb = (a >> 8) & 255, (b >> 8) & 255
    transfer = (ta - tb) >> 2  # Legacy helper's specified arithmetic shift, not the ca-v2 heat law.
    sx = ((a >> 16) & 15)
    sy = ((a >> 20) & 15)
    output = np.column_stack((a, a & 255, ta, sx - (sx >= 8) * 16, sy - (sy >= 8) * 16,
                              (a >> 24) & 15, (a >> 28) & 15,
                              (a & 0xffff00ff) | (np.clip(ta - transfer, 0, 255) << 8),
                              (b & 0xffff00ff) | (np.clip(tb + transfer, 0, 255) << 8)))
    return (output & 0xffffffff).astype(np.uint32)


def codec_trial(device, source: str, vectors: np.ndarray, *, warmup: int = 2, samples: int = 7) -> dict:
    errors = candidate_lint(source, "codec")
    if errors:
        raise ValueError("; ".join(errors))
    if vectors.dtype != np.uint32 or vectors.ndim != 2 or vectors.shape[1] != 2 or len(vectors) == 0:
        raise ValueError("Codec probes require a nonempty Nx2 uint32 array")
    if type(warmup) is not int or warmup < 1 or type(samples) is not int or samples < 3:
        raise ValueError("Codec timing requires warmup and at least three samples")
    full_source = shader_source("bitmask_defs.wgsl") + "\n" + source + "\n" + HARNESS
    module = device.create_shader_module(code=full_source)
    pipeline = device.create_compute_pipeline(layout="auto", compute={"module": module, "entry_point": "probe"})
    with ExitStack() as resources:
        def keep(buffer):
            resources.callback(buffer.destroy)
            return buffer
        inputs = keep(device.create_buffer_with_data(data=vectors, usage=wgpu.BufferUsage.STORAGE))
        outputs = keep(device.create_buffer(size=len(vectors) * 9 * 4, usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC))
        group = device.create_bind_group(layout=pipeline.get_bind_group_layout(0), entries=[
            {"binding": 0, "resource": {"buffer": inputs}}, {"binding": 1, "resource": {"buffer": outputs}}])

        def dispatch():
            encoder = device.create_command_encoder()
            compute = encoder.begin_compute_pass()
            compute.set_pipeline(pipeline)
            compute.set_bind_group(0, group)
            compute.dispatch_workgroups((len(vectors) + 63) // 64)
            compute.end()
            device.queue.submit([encoder.finish()])

        for _ in range(warmup):
            synchronized_sample(device.queue, dispatch, outputs)
        actual = np.frombuffer(device.queue.read_buffer(outputs), dtype=np.uint32).reshape(-1, 9).copy()
        expected = codec_expected(vectors)
        timings = [synchronized_sample(device.queue, dispatch, outputs) for _ in range(samples)]
        return {"codec_pack_errors": int(np.count_nonzero(actual[:, 0] != expected[:, 0])),
                "codec_field_errors": int(np.count_nonzero(actual[:, 1:7] != expected[:, 1:7])),
                "codec_exchange_errors": int(np.count_nonzero(actual[:, 7:9] != expected[:, 7:9])),
                "timingMs": distribution(timings), "vectorsHash": digest(vectors.astype("<u4").tobytes()),
                "compiledHash": digest(full_source), "vectors": len(vectors)}

sources.eval/correctness.py:
"""Validate legacy codec seed helpers through the independent host-owned probe.

Successful seed probes are not evolution admission; use the composed evaluator.
"""

from pathlib import Path

from engine.runner import GPUTrialRunner, generate_test_data


def validate_seed(runner: GPUTrialRunner, shader_path: Path, n_voxels: int = 1_048_576) -> dict:
    result = runner.run_pack_unpack_trial(shader_path.read_text(encoding="utf-8"), generate_test_data(n_voxels))
    return {"shader": shader_path.name, **result}


def validate_all_seeds(n_voxels: int = 1_048_576):
    seeds = sorted((Path(__file__).resolve().parent.parent / "seeds/phase_1a").glob("*.wgsl"))
    if not seeds:
        raise ValueError("Codec seed validation requires at least one seed")
    with GPUTrialRunner() as runner:
        return [validate_seed(runner, path, n_voxels) for path in seeds]


if __name__ == "__main__":
    results = validate_all_seeds()
    for result in results:
        print(result)
    raise SystemExit(int(not results or any(result.get("passed") is not True for result in results)))

sources.eval/policy.py:
"""Fail-closed acceptance for optimizations of the current composed engine."""

import hashlib
import json
import math
import re
from dataclasses import asdict, dataclass

from engine.contracts import checked_integer
from engine.schedule import KERNEL_SPECS


POLICY_VERSION = "ca-v2-evaluation-1"
TARGETS = {
    "codec": "phase_1a_winner.wgsl", "thermal": "phase_2a_winner.wgsl",
    "gravity": "phase_2b_winner.wgsl", "diagonal": "phase_2b_diagonal_winner.wgsl",
    "liquid": "phase_2b_liquid_winner.wgsl", "buoyancy": "phase_2b_gas_buoyancy_winner.wgsl",
    "spread": "phase_2b_gas_spread_winner.wgsl", "phase": "phase_2c_winner.wgsl",
    "combustion": "phase_2d_winner.wgsl",
}
ALIASES = {"1a": "codec", "2a": "thermal", "2b": "gravity", "2c": "phase", "2d": "combustion"}
OBJECTIVES = ("end_to_end_ms", "sync_tick_ms")


def target_name(value: str) -> str:
    value = ALIASES.get(value, value)
    if value not in TARGETS:
        raise ValueError("Unknown production target. Legacy phases 1b/1c are inactive ca-v1 experiments; they cannot be promoted.")
    return value


def canonical(value) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False).encode("utf-8")


def digest(value: bytes | str) -> str:
    return hashlib.sha256(value.encode("utf-8") if isinstance(value, str) else value).hexdigest()


@dataclass(frozen=True)
class EvaluationConfig:
    seed: int = 8173
    warmup: int = 2
    samples: int = 7
    ticks: int = 4
    timeout_seconds: int = 180

    def __post_init__(self):
        for name, low, high in (("seed", 0, 2**32 - 1), ("warmup", 1, 20), ("samples", 3, 50),
                                ("ticks", 4, 64), ("timeout_seconds", 30, 600)):
            checked_integer(getattr(self, name), low, high, name)

    def to_dict(self):
        return asdict(self)


def target_variants(target: str) -> set[str]:
    target = target_name(target)
    return {spec.id for spec in KERNEL_SPECS if target == "codec" or spec.source_file == TARGETS[target]}


def constraints(target: str) -> dict[str, int]:
    target = target_name(target)
    gates = {name: 0 for name in ("composed_mismatches", "energy_drift_q", "determinism_mismatches", "restart_mismatches")}
    gates["positive_variants_min"] = len(target_variants(target))
    gates["compared_passes_min"] = 1
    if target in ("thermal", "gravity", "diagonal", "liquid", "buoyancy", "spread"):
        gates["material_count_errors"] = 0
    if target == "codec":
        gates.update(codec_field_errors=0, codec_pack_errors=0, codec_exchange_errors=0)
    return gates


def acceptance_errors(fitness: dict, target: str) -> list[str]:
    """Only exact numeric evidence satisfies a gate; missing/NaN/bools fail."""
    gates = constraints(target)
    if not isinstance(fitness, dict):
        return ["Missing fitness"]
    errors = []
    if fitness.get("diverged", False) is not False or fitness.get("disqualified", False) is not False:
        errors.append("Candidate diverged or was disqualified")
    for key, required in gates.items():
        name = key.removesuffix("_min")
        actual = fitness.get(name)
        if type(actual) is not int or actual < 0:
            errors.append(f"{name}: missing or invalid integer evidence")
        elif (actual < required if key.endswith("_min") else actual != required):
            errors.append(f"{name}: {actual}, required {'at least ' if key.endswith('_min') else ''}{required}")
    for name in OBJECTIVES:
        actual = fitness.get(name)
        if type(actual) not in (int, float) or not math.isfinite(actual) or actual <= 0:
            errors.append(f"{name}: requires a finite positive synchronized measurement")
    return errors


def strip_comments(source: str) -> str:
    """WGSL block comments nest. Preserve length so offsets refer to exact input."""
    out, index, depth = [], 0, 0
    while index < len(source):
        pair = source[index:index + 2]
        if pair == "/*":
            depth += 1
            out.append("  ")
            index += 2
        elif depth and pair == "*/":
            depth -= 1
            out.append("  ")
            index += 2
        elif not depth and pair == "//":
            end = source.find("\n", index)
            end = len(source) if end < 0 else end
            out.append(" " * (end - index))
            index = end
        else:
            out.append(source[index] if not depth or source[index] == "\n" else " ")
            index += 1
    if depth:
        raise ValueError("Unterminated WGSL block comment")
    return "".join(out)


def candidate_lint(source: str, target: str) -> list[str]:
    """A bounded local optimization language, not a sandbox for hostile GPU code."""
    target = target_name(target)
    if type(source) is not str or not 1 <= len(source.encode("utf-8")) <= 65536:
        return ["SS024 candidate must contain 1..65536 UTF-8 bytes"]
    try:
        code = strip_comments(source)
    except ValueError as error:
        return [f"SS024 {error}"]
    errors = []
    if re.search(r"\b(?:while|loop|continuing|workgroupBarrier|storageBarrier|textureBarrier)\b", code):
        errors.append("SS024 unbounded loops and barriers are outside the candidate contract")
    for match in re.finditer(r"\bfor\s*\(([^)]*)\)\s*\{", code):
        bounded = re.fullmatch(r"\s*var\s+(\w+)\s*=\s*0u;\s*\1\s*<\s*(\d+)u;\s*\1\s*\+=\s*1u\s*", match.group(1))
        if bounded is None or not 1 <= int(bounded.group(2)) <= 64:
            errors.append("SS024 for loops require a literal bound from 1 through 64")
            continue
        depth, end = 1, match.end()
        while end < len(code) and depth:
            depth += (code[end] == "{") - (code[end] == "}")
            end += 1
        body = code[match.end():end - 1]
        name = re.escape(bounded.group(1))
        if re.search(rf"\b{name}\s*(?:[+*/%&|^<>-]*=(?!=)|\+\+|--)|&\s*{name}\b|\bvar\s+{name}\b", body):
            errors.append("SS024 loop induction variable must not be changed or aliased in its body")
    if len(re.findall(r"\bfor\b", code)) != len(list(re.finditer(r"\bfor\s*\([^)]*\)\s*\{", code))):
        errors.append("SS024 unsupported for-loop syntax")
    if re.search(r"@(?:group|binding)\b|\bvar\s*<\s*(?:storage|workgroup)\b", code):
        errors.append("SS025 candidate cannot replace host-owned storage or workgroup state")
    if target == "codec":
        if "@" in code or re.search(r"\b(?:grid_in|grid_out|energy_in|energy_out|cold_table)\b", code):
            errors.append("SS025 codec candidates contain helpers only, without entry points or storage access")
        names = re.findall(r"\bfn\s+(\w+)\s*\(", code)
        if any(names.count(name) != 1 for name in ("pack_voxel", "unpack_voxel", "exchange_thermal")):
            errors.append("SS025 codec must define each required helper exactly once")
    else:
        if (len(re.findall(r"@compute\b", code)) != 1 or len(re.findall(r"\bfn\s+tick\s*\(", code)) != 1
                or not re.search(r"@workgroup_size\(\s*16\s*,\s*16\s*\)", code)):
            errors.append("SS025 production candidates require one tick entry with workgroup_size(16,16)")
        if re.search(r"\b(?:grid_out|energy_out)\s*\[[^]]*\]\s*=", code):
            errors.append("SS025 candidate writes must transport both state arrays through io_copy/io_write")
    return errors

