// Independent CPU implementation, compiled from the exact checkout under test.
import { mkdtemp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, dirname, resolve, relative, isAbsolute } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import ts from 'typescript';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const temp = await mkdtemp(join(tmpdir(), 'state-space-reference-'));
try {
  async function compile(directory, destination) {
    await mkdir(destination, { recursive: true });
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      if (entry.isDirectory() && entry.name === 'generated') await compile(join(directory, entry.name), join(destination, entry.name));
      if (!entry.isFile() || !entry.name.endsWith('.ts') || entry.name.includes('.test.') || entry.name.startsWith('vite')) continue;
      const source = await readFile(join(directory, entry.name), 'utf8');
      const compiled = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ES2022 } });
      await writeFile(join(destination, entry.name.replace(/\.ts$/, '.js')), compiled.outputText);
    }
  }
  await writeFile(join(temp, 'package.json'), '{"type":"module"}');
  await compile(join(root, 'engine'), temp);
  const { runCpuTick } = await import(pathToFileURL(join(temp, 'cpu_physics.js')));
  const { createMaterialRegistry } = await import(pathToFileURL(join(temp, 'registry.js')));
  let input = '';
  for await (const chunk of process.stdin) input += chunk;
  const cases = JSON.parse(input);
  if (!Array.isArray(cases) || cases.length === 0) throw new Error('Reference cases must be nonempty');
  const output = [];
  for (const scene of cases) {
    const registry = await createMaterialRegistry(scene.catalog);
    const cold = registry.coldTable();
    let state = { grid: Uint32Array.from(scene.cells), energyQ: Uint32Array.from(scene.energyQ) };
    const passes = [];
    for (let tick = scene.tick; tick < scene.tick + scene.ticks; tick += 1) {
      state = runCpuTick(state, scene.width, scene.height, cold, tick, (id, value) => {
        passes.push({ tick, id, cells: Array.from(value.grid), energyQ: Array.from(value.energyQ) });
      }, registry);
    }
    output.push({ name: scene.name, passes });
  }
  process.stdout.write(JSON.stringify(output));
} finally {
  const relativeTemp = relative(resolve(tmpdir()), resolve(temp));
  if (isAbsolute(relativeTemp) || relativeTemp.startsWith('..') || !relativeTemp.startsWith('state-space-reference-')) throw new Error('Unexpected reference cleanup path');
  await rm(temp, { recursive: true, force: true });
}

sources.eval/scenes.py:
"""Versioned, seeded acceptance and performance workloads."""

import copy

import numpy as np

from engine.conformance import conformance_cases
from engine.registry import DEFAULT_REGISTRY
from engine.schema import VoxelState, pack_voxel
from engine.state import seed_state, thermal_view


KINDS = ("sparse", "dense", "thermal", "reactive")


def cell(material: int, thermal: int = 20, flags: int = 0, registry=DEFAULT_REGISTRY) -> int:
    record = registry.material(material)
    return pack_voxel(VoxelState(material, thermal, 0, 0, record["properties"]["default_phase"], flags))


def prepared(scene: dict, registry=DEFAULT_REGISTRY, fractional_seed: int | None = None) -> dict:
    cells, energy = seed_state(np.array(scene["cells"], dtype=np.uint32), registry._model)
    if fractional_seed is not None:
        rng = np.random.default_rng(fractional_seed)
        energy += rng.integers(1, 500 * 256, size=energy.size, dtype=np.uint32)
        cells = thermal_view(cells, energy, registry._model)
    return {**scene, "cells": cells.tolist(), "energyQ": energy.tolist(), "catalog": registry.to_dict()}


def workload(width: int, height: int, kind: str, seed: int, ticks: int) -> dict:
    if kind not in KINDS:
        raise ValueError("Unknown benchmark workload")
    rng = np.random.default_rng(seed)
    grid = np.full(width * height, cell(0), dtype=np.uint32)
    for y in range(height):
        for x in range(width):
            index = y * width + x
            if x in (0, width - 1) or y == height - 1:
                grid[index] = cell(1)
            elif kind == "sparse":
                if rng.random() < .03:
                    grid[index] = cell(int(rng.choice([2, 3, 14])), 160, int(rng.integers(0, 16)))
            elif kind == "dense":
                grid[index] = cell(int(rng.choice([0, 2, 3, 6, 14])), 25, int(rng.integers(0, 16)))
            elif kind == "thermal":
                grid[index] = cell(5, 255 if (x + y) % 2 else 0)
            else:
                grid[index] = cell(int(rng.choice([0, 0, 0, 2, 7, 8, 9, 6])), int(rng.integers(20, 256)))
    return prepared({"name": f"{kind}-{width}x{height}", "width": width, "height": height,
                     "tick": 3, "ticks": ticks, "cells": grid.tolist()},
                    fractional_seed=seed if kind == "thermal" else None)


def acceptance_cases(seed: int) -> list[dict]:
    cases = [prepared(scene, fractional_seed=seed if scene["name"].endswith("-2") else None)
             for scene in conformance_cases()]
    cases.extend(workload(33, 17, kind, seed + index, 4) for index, kind in enumerate(KINDS))
    # Custom IDs exercise registry-driven behavior, including the highest allowed ID.
    catalog = DEFAULT_REGISTRY.to_dict()
    records = {record["id"]: record for record in catalog["materials"]}
    powder = copy.deepcopy(records[3])
    powder.update(id=255, name="evaluation_grit")
    metal = copy.deepcopy(records[5])
    metal.update(id=18, name="evaluation_copper")
    liquid = copy.deepcopy(records[16])
    liquid.update(id=19, name="evaluation_molten_copper")
    metal["properties"].update(melt_point=80, latent_heat_melt=20, melts_into=19)
    liquid["properties"].update(freeze_point=60, latent_heat_melt=20, freezes_into=18, phase_energy=20)
    registry = DEFAULT_REGISTRY.extend([powder, metal, liquid])
    grid = [cell(0)] * (9 * 7)
    for x in range(9):
        grid[6 * 9 + x] = cell(1)
    grid[12], grid[13], grid[23] = cell(255, 20, 15, registry), cell(18, 150, 9, registry), cell(19, 20, 8, registry)
    cases.append(prepared({"name": "custom-registry", "width": 9, "height": 7, "tick": 7, "ticks": 5, "cells": grid}, registry))
    return cases

sources.locked/phase_1a_winner.wgsl:
// Seed 2: Branchless optimized pack/unpack
// Uses bitwise tricks to avoid branching for sign extension.

fn pack_voxel(mat: u32, thermal: u32, kx: i32, ky: i32, phase: u32, flags: u32) -> u32 {
    // Single expression pack — compiler can fuse these
    return ((mat & MATERIAL_MASK) << MATERIAL_SHIFT)
         | ((thermal & THERMAL_MASK) << THERMAL_SHIFT)
         | ((u32(kx) & KINETIC_X_MASK) << KINETIC_X_SHIFT)
         | ((u32(ky) & KINETIC_Y_MASK) << KINETIC_Y_SHIFT)
         | ((phase & PHASE_MASK) << PHASE_SHIFT)
         | ((flags & FLAGS_MASK) << FLAGS_SHIFT);
}

fn unpack_voxel(packed: u32) -> VoxelState {
    var state: VoxelState;
    state.material = (packed >> MATERIAL_SHIFT) & MATERIAL_MASK;
    state.thermal = (packed >> THERMAL_SHIFT) & THERMAL_MASK;

    // Branchless sign extension: (val ^ 0x8) - 0x8 converts 4-bit unsigned to signed
    let kx_raw = (packed >> KINETIC_X_SHIFT) & KINETIC_X_MASK;
    let ky_raw = (packed >> KINETIC_Y_SHIFT) & KINETIC_Y_MASK;
    state.kinetic_x = i32((kx_raw ^ 0x8u) - 0x8u);
    state.kinetic_y = i32((ky_raw ^ 0x8u) - 0x8u);

    state.phase = (packed >> PHASE_SHIFT) & PHASE_MASK;
    state.flags = (packed >> FLAGS_SHIFT) & FLAGS_MASK;
    return state;
}

fn exchange_thermal(a: u32, b: u32) -> vec2<u32> {
    // Branchless thermal exchange with configurable rate
    let ta = (a >> THERMAL_SHIFT) & THERMAL_MASK;
    let tb = (b >> THERMAL_SHIFT) & THERMAL_MASK;

    // Arithmetic shift for signed division
    let diff = i32(ta) - i32(tb);
    let transfer = diff >> 2;  // Divide by 4 via shift

    let new_ta = u32(max(min(i32(ta) - transfer, 255), 0));
    let new_tb = u32(max(min(i32(tb) + transfer, 255), 0));

    let clear_mask = ~(THERMAL_MASK << THERMAL_SHIFT);
    return vec2<u32>(
        (a & clear_mask) | (new_ta << THERMAL_SHIFT),
        (b & clear_mask) | (new_tb << THERMAL_SHIFT)
    );
}

// ── Compute entry point ────────────────────────────────────────────

@group(0) @binding(0) var<storage, read> input: array<u32>;
@group(0) @binding(1) var<storage, read_write> output: array<u32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let idx = gid.x;
    if (idx >= arrayLength(&input)) {
        return;
    }

    let packed = input[idx];
    let state = unpack_voxel(packed);
    let repacked = pack_voxel(
        state.material, state.thermal,
        state.kinetic_x, state.kinetic_y,
        state.phase, state.flags
    );
    output[idx] = repacked;
}

sources.locked/phase_1b_winner.wgsl:
// Block-based thermal diffusion with bit-packed neighbor processing
// Packs multiple neighbor thermal values into u32s for parallel processing

@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;

fn get_idx(x: u32, y: u32) -> u32 {
    return y * GRID_WIDTH + x;
}

fn get_thermal(packed: u32) -> u32 {
    return (packed >> THERMAL_SHIFT) & THERMAL_MASK;
}

fn get_material(packed: u32) -> u32 {
    return (packed >> MATERIAL_SHIFT) & MATERIAL_MASK;
}

fn set_thermal(packed: u32, thermal: u32) -> u32 {
    let clear_mask = ~(THERMAL_MASK << THERMAL_SHIFT);
    return (packed & clear_mask) | ((thermal & THERMAL_MASK) << THERMAL_SHIFT);
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;

    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) {
        return;
    }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    let mat = get_material(voxel);
    if (mat == MAT_AIR) {
        grid_out[idx] = voxel;
        return;
    }

    // Block-based pattern: 2x2 blocks process in different phases
    let block_phase = ((x >> 1u) + (y >> 1u)) & 3u;
    let self_thermal = get_thermal(voxel);

    // Start with heavily weighted self
    var thermal_sum = self_thermal << 4u; // *16 via shift
    var weight_sum = 16u;

    // Pack neighbor data for vectorized processing
    // We'll read all 8 neighbors and pack their thermal/valid bits
    var packed_cardinals = vec4<u32>(0u, 0u, 0u, 0u); // N, E, S, W thermals
    var packed_diagonals = vec4<u32>(0u, 0u, 0u, 0u); // NE, SE, SW, NW thermals
    var valid_mask = 0u; // Bit i set if neighbor i is valid (not air)

    // North (bit 0)
    if (y > 0u) {
        let north = grid_in[idx - GRID_WIDTH];
        if (get_material(north) != MAT_AIR) {
            packed_cardinals.x = get_thermal(north);
            valid_mask = valid_mask | 1u;
        }
    }

    // East (bit 1)
    if (x < GRID_WIDTH - 1u) {
        let east = grid_in[idx + 1u];
        if (get_material(east) != MAT_AIR) {
            packed_cardinals.y = get_thermal(east);
            valid_mask = valid_mask | 2u;
        }
    }

    // South (bit 2)
    if (y < GRID_HEIGHT - 1u) {
        let south = grid_in[idx + GRID_WIDTH];
        if (get_material(south) != MAT_AIR) {
            packed_cardinals.z = get_thermal(south);
            valid_mask = valid_mask | 4u;
        }
    }

    // West (bit 3)
    if (x > 0u) {
        let west = grid_in[idx - 1u];
        if (get_material(west) != MAT_AIR) {
            packed_cardinals.w = get_thermal(west);
            valid_mask = valid_mask | 8u;
        }
    }

    // Process diagonals based on block phase to avoid conflicts
    if ((block_phase & 1u) == 0u) {
        // Northeast (bit 4)
        if (x < GRID_WIDTH - 1u && y > 0u) {
            let ne = grid_in[idx - GRID_WIDTH + 1u];
            if (get_material(ne) != MAT_AIR) {
                packed_diagonals.x = get_thermal(ne);
                valid_mask = valid_mask | 16u;
            }
        }

        // Southwest (bit 5)
        if (x > 0u && y < GRID_HEIGHT - 1u) {
            let sw = grid_in[idx + GRID_WIDTH - 1u];
            if (get_material(sw) != MAT_AIR) {
                packed_diagonals.z = get_thermal(sw);
                valid_mask = valid_mask | 32u;
            }
        }
    }

    if (block_phase >= 2u) {
        // Southeast (bit 6)
        if (x < GRID_WIDTH - 1u && y < GRID_HEIGHT - 1u) {
            let se = grid_in[idx + GRID_WIDTH + 1u];
            if (get_material(se) != MAT_AIR) {
                packed_diagonals.y = get_thermal(se);
                valid_mask = valid_mask | 64u;
            }
        }

        // Northwest (bit 7)
        if (x > 0u && y > 0u) {
            let nw = grid_in[idx - GRID_WIDTH - 1u];
            if (get_material(nw) != MAT_AIR) {
                packed_diagonals.w = get_thermal(nw);
                valid_mask = valid_mask | 128u;
            }
        }
    }

    // Vectorized thermal accumulation
    // Cardinals get 2x weight
    let cardinal_valid = vec4<u32>(
        (valid_mask >> 0u) & 1u,
        (valid_mask >> 1u) & 1u,
        (valid_mask >> 2u) & 1u,
        (valid_mask >> 3u) & 1u
    );

    let diagonal_valid = vec4<u32>(
        (valid_mask >> 4u) & 1u,
        (valid_mask >> 5u) & 1u,
        (valid_mask >> 6u) & 1u,
        (valid_mask >> 7u) & 1u
    );

    // Parallel dot products for thermal sums
    let cardinal_sum = dot(packed_cardinals, cardinal_valid);
    let diagonal_sum = dot(packed_diagonals, diagonal_valid);
    let cardinal_count = dot(cardinal_valid, vec4<u32>(1u, 1u, 1u, 1u));
    let diagonal_count = dot(diagonal_valid, vec4<u32>(1u, 1u, 1u, 1u));

    // Accumulate with weights
    thermal_sum = thermal_sum + (cardinal_sum << 1u) + diagonal_sum;
    weight_sum = weight_sum + (cardinal_count << 1u) + diagonal_count;

    // Compute average
    let new_thermal = thermal_sum / weight_sum;
    grid_out[idx] = set_thermal(voxel, new_thermal);
}

sources.locked/phase_1c_winner.wgsl:
// Seed 2: Border-aware activity scan wrapping Phase 1b winner
// Checks tile + 1-pixel border halo for activity.
// A tile wakes if ANY voxel in the tile or its immediate border is non-air.
// This correctly handles thermal diffusion across tile boundaries.

@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;
@group(0) @binding(2) var<storage, read_write> active_counter: array<atomic<u32>>;

var<workgroup> has_active: u32;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(packed: u32) -> u32 { return (packed >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_thermal(packed: u32) -> u32 { return (packed >> THERMAL_SHIFT) & THERMAL_MASK; }
fn set_thermal(packed: u32, thermal: u32) -> u32 {
    return (packed & ~(THERMAL_MASK << THERMAL_SHIFT)) | ((thermal & THERMAL_MASK) << THERMAL_SHIFT);
}

fn process_voxel(x: u32, y: u32) {
    let idx = get_idx(x, y);
    let voxel = grid_in[idx];
    let mat = get_material(voxel);
    if (mat == MAT_AIR) { grid_out[idx] = voxel; return; }

    let block_phase = ((x >> 1u) + (y >> 1u)) & 3u;
    let self_thermal = get_thermal(voxel);
    var thermal_sum = self_thermal << 4u;
    var weight_sum = 16u;
    var packed_cardinals = vec4<u32>(0u, 0u, 0u, 0u);
    var packed_diagonals = vec4<u32>(0u, 0u, 0u, 0u);
    var valid_mask = 0u;

    if (y > 0u) { let n = grid_in[idx - GRID_WIDTH]; if (get_material(n) != MAT_AIR) { packed_cardinals.x = get_thermal(n); valid_mask |= 1u; } }
    if (x < GRID_WIDTH - 1u) { let n = grid_in[idx + 1u]; if (get_material(n) != MAT_AIR) { packed_cardinals.y = get_thermal(n); valid_mask |= 2u; } }
    if (y < GRID_HEIGHT - 1u) { let n = grid_in[idx + GRID_WIDTH]; if (get_material(n) != MAT_AIR) { packed_cardinals.z = get_thermal(n); valid_mask |= 4u; } }
    if (x > 0u) { let n = grid_in[idx - 1u]; if (get_material(n) != MAT_AIR) { packed_cardinals.w = get_thermal(n); valid_mask |= 8u; } }

    if ((block_phase & 1u) == 0u) {
        if (x < GRID_WIDTH - 1u && y > 0u) { let n = grid_in[idx - GRID_WIDTH + 1u]; if (get_material(n) != MAT_AIR) { packed_diagonals.x = get_thermal(n); valid_mask |= 16u; } }
        if (x > 0u && y < GRID_HEIGHT - 1u) { let n = grid_in[idx + GRID_WIDTH - 1u]; if (get_material(n) != MAT_AIR) { packed_diagonals.z = get_thermal(n); valid_mask |= 32u; } }
    }
    if (block_phase >= 2u) {
        if (x < GRID_WIDTH - 1u && y < GRID_HEIGHT - 1u) { let n = grid_in[idx + GRID_WIDTH + 1u]; if (get_material(n) != MAT_AIR) { packed_diagonals.y = get_thermal(n); valid_mask |= 64u; } }
        if (x > 0u && y > 0u) { let n = grid_in[idx - GRID_WIDTH - 1u]; if (get_material(n) != MAT_AIR) { packed_diagonals.w = get_thermal(n); valid_mask |= 128u; } }
    }

    let cv = vec4<u32>((valid_mask) & 1u, (valid_mask >> 1u) & 1u, (valid_mask >> 2u) & 1u, (valid_mask >> 3u) & 1u);
    let dv = vec4<u32>((valid_mask >> 4u) & 1u, (valid_mask >> 5u) & 1u, (valid_mask >> 6u) & 1u, (valid_mask >> 7u) & 1u);
    thermal_sum += (dot(packed_cardinals, cv) << 1u) + dot(packed_diagonals, dv);
    weight_sum += (dot(cv, vec4<u32>(1u, 1u, 1u, 1u)) << 1u) + dot(dv, vec4<u32>(1u, 1u, 1u, 1u));
    grid_out[idx] = set_thermal(voxel, thermal_sum / weight_sum);
}

fn is_active_at(sx: i32, sy: i32) -> bool {
    if (sx < 0 || sy < 0 || sx >= i32(GRID_WIDTH) || sy >= i32(GRID_HEIGHT)) { return false; }
    return get_material(grid_in[u32(sy) * GRID_WIDTH + u32(sx)]) != MAT_AIR;
}

@compute @workgroup_size(16, 16)
fn tick(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let x = gid.x;
    let y = gid.y;
    let local_idx = lid.y * 16u + lid.x;
    let is_in_bounds = x < GRID_WIDTH && y < GRID_HEIGHT;

    if (local_idx == 0u) { has_active = 0u; }
    workgroupBarrier();

    // Check own voxel
    if (is_in_bounds && get_material(grid_in[get_idx(x, y)]) != MAT_AIR) {
        has_active = 1u;
    }
    // Edge threads check border halo
    if (lid.x == 0u && is_active_at(i32(x) - 1, i32(y))) { has_active = 1u; }
    if (lid.x == 15u && is_active_at(i32(x) + 1, i32(y))) { has_active = 1u; }
    if (lid.y == 0u && is_active_at(i32(x), i32(y) - 1)) { has_active = 1u; }
    if (lid.y == 15u && is_active_at(i32(x), i32(y) + 1)) { has_active = 1u; }
    workgroupBarrier();

    if (has_active == 0u) {
        if (is_in_bounds) { grid_out[get_idx(x, y)] = grid_in[get_idx(x, y)]; }
        return;
    }

    if (local_idx == 0u) { atomicAdd(&active_counter[0], 1u); }
    if (is_in_bounds) { process_voxel(x, y); }
}

