    let idx = get_idx(x, y);
    let voxel = grid_in[idx];

    var pair_left = x;
    if (((x + MOVE_PHASE) & 1u) != 0u) {
        if (x == 0u) {
            io_copy(idx, idx);
            return;
        }
        pair_left = x - 1u;
